#include <stdio.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double area2(Point a, Point b, Point c) {
    return fabs(cross(a, b, c));
}

double polygonArea(Point *p, int n) {
    double area = 0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        area += p[i].x * p[j].y;
        area -= p[j].x * p[i].y;
    }
    return fabs(area) / 2.0;
}

double dist(Point a, Point b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return sqrt(dx*dx + dy*dy);
}

Point pointOnEdge(Point *p, int n, double pos) {
    double walked = 0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        double len = dist(p[i], p[j]);
        if (walked + len >= pos) {
            double t = (pos - walked) / len;
            Point res;
            res.x = p[i].x + t * (p[j].x - p[i].x);
            res.y = p[i].y + t * (p[j].y - p[i].y);
            return res;
        }
        walked += len;
    }
    return p[0];
}

double areaToPoint(Point *p, int n, Point a, Point b) {
    // area of polygon from a to b along perimeter (clockwise)
    double area = 0;
    int startEdge = -1, endEdge = -1;
    double startPos = -1, endPos = -1;
    double walked = 0;
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        double len = dist(p[i], p[j]);
        if (fabs(dist(p[i], a) + dist(a, p[j]) - len) < 1e-9) {
            startEdge = i;
            startPos = walked + dist(p[i], a);
        }
        if (fabs(dist(p[i], b) + dist(b, p[j]) - len) < 1e-9) {
            endEdge = i;
            endPos = walked + dist(p[i], b);
        }
        walked += len;
    }

    // Compute area from a to b clockwise
    double total = 0;
    Point cur = a;
    int idx = startEdge;
    double pos = startPos;
    double perim = walked; // total perimeter

    while (1) {
        int next = (idx + 1) % n;
        double edgeLen = dist(p[idx], p[next]);
        double nextPos = pos + edgeLen;

        if (nextPos >= endPos || (idx == endEdge && fabs(nextPos - endPos) < 1e-9)) {
            Point end = b;
            total += cross(cur, p[next], end);
            break;
        } else {
            total += cross(cur, p[next], p[next]);
            cur = p[next];
            idx = next;
            pos = nextPos;
        }
    }
    return fabs(total) / 2.0;
}

