#define MAXN 105
#define SAMPLES 100000

typedef struct { double x, y; } P;

int n;
P poly[MAXN];
double totalArea;

// Area of triangle
double triArea(P a, P b, P c) {
    return 0.5 * ((b.x-a.x)*(c.y-a.y) - (c.x-a.x)*(b.y-a.y));
}

// Get point on boundary given parameter t in [0, n) where integer part is edge index
P getPoint(double t) {
    int i = (int)t % n;
    double f = t - (int)t;
    P a = poly[i], b = poly[(i+1)%n];
    return (P){a.x + f*(b.x-a.x), a.y + f*(b.y-a.y)};
}

// Compute signed area from boundary point t1 to t2 (going forward), forming polygon with origin
// Area of sub-polygon: t1 -> vertices -> t2 -> back to t1
double subArea(double t1, double t2) {
    // sub-polygon: p1, then vertices from ceil(t1) to floor(t2), then p2
    P p1 = getPoint(t1), p2 = getPoint(t2);
    double area = 0;
    P ref = p1;
    int start = ((int)t1 + 1) % n;
    // collect vertices between t1 and t2
    // number of full edges
    int i = (int)t1 + 1;
    int end = (int)t2;
    // use shoelace with ref point
    P prev = p1;
    for (int k = i; k <= end; k++) {
        P cur = poly[k % n];
        area += triArea(ref, prev, cur);
        prev = cur;
    }
    area += triArea(ref, prev, p2);
    return fabs(area);
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

static const double EPS = 1e-12;

static Point *P;
static int n;
static double *pref;   // prefix of cross products
static double total2;  // twice polygon area, positive

static double cross_pt(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
}

static Point sub(Point a, Point b) {
    Point r = {a.x - b.x, a.y - b.y};
    return r;
}

static Point add(Point a, Point b) {
    Point r = {a.x + b.x, a.y + b.y};
    return r;
}

static Point mul(Point a, double t) {
    Point r = {a.x * t, a.y * t};
    return r;
}

static double dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

static double norm(Point a) {
    return sqrt(dot(a, a));
}

static Point get_point_on_edge(int i, double t) {
    // edge i: P[i] -> P[(i+1)%n], t in [0,1]
    Point a = P[i];
    Point b = P[(i + 1) % n];
    return add(a, mul(sub(b, a), t));
}

static double area2_chain(int i, double ti, int j, double tj) {
    // Twice signed area of polygonal chain:
    // A = point on edge i at ti
    // then vertices i+1, i+2, ..., j
    // then B = point on edge j at tj
    // and back to A
    // Assumes forward CCW traversal from A to B.
    Point A = get_point_on_edge(i, ti);
    Point B = get_point_on_edge(j, tj);

    double s = 0.0;
    s += cross_pt(A, P[(i + 1) % n]);

    int start = i + 1;
    int end = j;
    if (start <= end) {
        s += pref[end] - pref[start];
    }

    s += cross_pt(P[j], B);
    s += cross_pt(B, A);
    return s;
}

static double f_for_fixed_i(int i, double ti, int j, double tj) {
    // area2_chain - total2/2
    return area2_chain(i, ti, j, tj) - total2 * 0.5;
}

int main(void) {
    if (scanf("%d", &n) != 1) return 0;

    P = (Point*)malloc(sizeof(Point) * n);
    pref = (double*)malloc(sizeof(double) * (n + 1));

    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &P[i].x, &P[i].y);
    }

    pref[0] = 0.0;
    for (int i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + cross_pt(P[i], P[(i + 1) % n]);
    }
    total2 = pref[n];
    if (total2 < 0) {
        // reverse to make CCW
        for (int i = 0; i < n / 2; i++) {
            Point tmp = P[i];
            P[i] = P[n - 1 - i];
            P[n - 1 - i] = tmp;
        }
        pref[0] = 0.0;
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + cross_pt(P[i], P[(i + 1) % n]);
        }
        total2 = pref[n];
    }

    double minLen = 1e100;
    double maxLen = 0.0;

    int j = 0;
    double tj = 0.0;

    // Initialize j,tj for i=0, ti=0 by advancing until half-area is reached
    while (1) {
        double val_end = f_for_fixed_i(0, 0.0, j, 1.0);
        if (val_end >= -EPS) break;
        j = (j + 1) % n;
    }
    {
        double low = 0.0, high = 1.0;
        for (int it = 0; it < 80; it++) {
            double mid = (low + high) * 0.5;
            double v = f_for_fixed_i(0, 0.0, j, mid);
            if (v >= 0.0) high = mid;
            else low = mid;
        }
        tj = (low + high) * 0.5;
    }

    for (int i = 0; i < n; i++) {
        // For each ti in [0,1], corresponding point on edge j moves monotonically forward.
        // We sample the solution at ti=0 and ti=1; the segment length between the two boundary points
        // is a convex function of ti on this interval, so extrema are at endpoints.
        for (int endp = 0; endp < 2; endp++) {
            double ti = (double)endp;

            // Move j,tj forward if needed to satisfy f(i,ti,j,1) >= 0
            while (1) {
                double val_end = f_for_fixed_i(i, ti, j, 1.0);
                if (val_end >= -EPS) break;
                j = (j + 1) % n;
                tj = 0.0;
            }

            // Solve on current edge j
            double low = 0.0, high = 1.0;
            for (int it = 0; it < 80; it++) {
                double mid = (low + high) * 0.5;
                double v = f_for_fixed_i(i, ti, j, mid);
                if (v >= 0.0) high = mid;
                else low = mid;
            }
            tj = (low + high) * 0.5;

            Point A = get_point_on_edge(i, ti);
            Point B = get_point_on_edge(j, tj);
            double len = norm(sub(B, A));
            if (len < minLen) minLen = len;
            if (len > maxLen) maxLen = len;
        }

        // advance i to next edge; keep current solution as starting point
    }

    printf("%.10f %.10f\n", minLen, maxLen);

    free(P);
    free(pref);
    return 0;
}

