public class ChocolateCut {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Point2D.Double[] poly = new Point2D.Double[n];
        for (int i = 0; i < n; i++) {
            poly[i] = new Point2D.Double(sc.nextDouble(), sc.nextDouble());
        }

        double totalArea = area(poly);
        double half = totalArea / 2.0;

        // prefix sums of edge lengths and cumulative area from vertex 0
        double[] edgeLen = new double[n];
        double[] cumArea = new double[n + 1]; // cumArea[i] = area from vertex 0 to i
        for (int i = 0; i < n; i++) {
            Point2D.Double a = poly[i];
            Point2D.Double b = poly[(i + 1) % n];
            edgeLen[i] = a.distance(b);
        }
        // cumulative area from vertex 0 to i (i vertices, edges between them)
        cumArea[0] = 0;
        for (int i = 0; i < n; i++) {
            int next = (i + 1) % n;
            cumArea[i + 1] = cumArea[i] + cross(poly[i], poly[next]);
        }
        double totalAreaCheck = Math.abs(cumArea[n]) / 2.0;
        half = totalAreaCheck / 2.0;

        // We'll use a two-pointer on doubled polygon for easy modulo
        int m = 2 * n;
        Point2D.Double[] dpoly = new Point2D.Double[m];
        double[] dedgeLen = new double[m];
        double[] dcumArea = new double[m + 1];
        for (int i = 0; i < m; i++) {
            dpoly[i] = poly[i % n];
            if (i < m - 1) {
                dedgeLen[i] = edgeLen[i % n];
            }
        }
        // cumulative "signed double area" from 0 to i
        dcumArea[0] = 0;
        for (int i = 0; i < m; i++) {
            int next = (i + 1) % m;
            dcumArea[i + 1] = dcumArea[i] + cross(dpoly[i], dpoly[next]);
        }

        double minLen = Double.MAX_VALUE;
        double maxLen = 0.0;

        int j = 0;
        for (int i = 0; i < n; i++) {
            // Ensure j starts at least i+1, area from i to j < half
            if (j <= i) j = i + 1;
            while (true) {
                double areaIJ = Math.abs(dcumArea[j] - dcumArea[i] + cross(dpoly[j % n], dpoly[i])) / 2.0;
                if (areaIJ >= half - 1e-12) break;
                j++;
            }
            // Now area from i to j is >= half, interpolate on edge (j-1)->j
            int prev = j - 1;
            double areaPrev = Math.abs(dcumArea[prev] - dcumArea[i] + cross(dpoly[prev % n], dpoly[i])) / 2.0;
            double needed = half - areaPrev;
            double edgeA = cross(dpoly[prev % n], dpoly[j % n]); // double area of triangle i,prev,j
            // Actually we need fraction along edge prev->j
            double segLen = dpoly[prev % n].distance(dpoly[j % n]);
            double frac = needed / (Math.abs(cross(dpoly[prev % n], dpoly[j % n])) / 2.0);
            if (frac < 0) frac = 0;
            if (frac > 1) frac = 1;
            double x = dpoly[prev % n].x + frac * (dpoly[j % n].x - dpoly[prev % n].x);
            double y = dpoly[prev % n].y + frac * (dpoly[j % n].y - dpoly[prev % n].y);
            Point2D.Double cutPoint = new Point2D.Double(x, y);
            double chordLen = dpoly[i].distance(cutPoint);
            minLen = Math.min(minLen, chordLen);
            maxLen = Math.max(maxLen, chordLen);
        }

        System.out.printf("%.15f %.15f%n", minLen, maxLen);
    }

    static double area(Point2D.Double[] p) {
        double sum = 0;
        int n = p.length;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            sum += p[i].x * p[j].y - p[j].x * p[i].y;
        }
        return Math.abs(sum) / 2.0;
    }

    static double cross(Point2D.Double a, Point2D.Double b) {
        return a.x * b.y - b.x * a.y;
    }
}

