import java.io.*;
import java.util.*;

/*
We need the minimum and maximum lengths of a straight segment whose endpoints lie on the boundary
of a convex polygon and which splits the polygon into two equal areas.

Key facts:
- For any direction, there is a unique equal-area chord orthogonal to that direction.
- As the direction rotates, the endpoints move continuously along the boundary.
- While endpoints lie on fixed edges, the chord length as a function of the direction parameter
  is a ratio of linear / linear functions, so any extremum on that interval occurs at an endpoint.
- Therefore global min/max occur when at least one endpoint is a vertex.
- For a fixed boundary point P, the other endpoint Q that makes area(P..Q along CCW chain) = total/2
  is unique and can be found by monotonic two-pointers over edges.

So we enumerate all vertices as one endpoint, find the matching point on the boundary giving half area,
compute the chord length. By symmetry, every extremal chord is encountered.

Implementation details:
- Duplicate vertices to handle circular indexing.
- Prefix sums of cross products give area of chains quickly.
- Two-pointer j moves monotonically, total O(n).
- For vertex i, find j such that area from i to j is <= half, and adding next edge exceeds half.
  Then Q lies on edge (j, j+1), at a fraction t solving linear area equation.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double val = 0;
            while (c > ' ' && c != '.' && c != -1) {
                val = val * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 1;
                c = read();
                while (c > ' ' && c != -1) {
                    mul *= 0.1;
                    val += (c - '0') * mul;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) Math.round(nextDouble());
        }
    }

    static class Pt {
        double x, y;
        Pt(double x, double y) { this.x = x; this.y = y; }
    }

    static double cross(Pt a, Pt b) {
        return a.x * b.y - a.y * b.x;
    }

    static double cross(Pt a, Pt b, Pt c) {
        return cross(new Pt(b.x - a.x, b.y - a.y), new Pt(c.x - a.x, c.y - a.y));
    }

    static double dist(Pt a, Pt b) {
        double dx = a.x - b.x, dy = a.y - b.y;
        return Math.hypot(dx, dy);
    }

    // doubled area of chain polygon: p[i], p[i+1], ..., p[j]
    // meaning polygon with those consecutive vertices only
    static double chainArea2(Pt[] p, double[] pref, int i, int j) {
        if (j <= i + 1) return 0.0;
        // sum cross(p[k], p[k+1]) for k=i..j-1 plus cross(p[j], p[i])
        return (pref[j] - pref[i]) + cross(p[j], p[i]);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        Pt[] orig = new Pt[n];
        for (int i = 0; i < n; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            orig[i] = new Pt(x, y);
        }

        // Ensure CCW orientation
        double total2 = 0;
        for (int i = 0; i < n; i++) total2 += cross(orig[i], orig[(i + 1) % n]);
        if (total2 < 0) {
            for (int i = 0; i < n / 2; i++) {
                Pt tmp = orig[i];
                orig[i] = orig[n - 1 - i];
                orig[n - 1 - i] = tmp;
            }
            total2 = -total2;
        }

        double half2 = total2 / 2.0;

        Pt[] p = new Pt[2 * n + 1];
        for (int i = 0; i < 2 * n; i++) p[i] = orig[i % n];
        p[2 * n] = p[0];

        double[] pref = new double[2 * n + 1];
        pref[0] = 0;
        for (int i = 0; i < 2 * n; i++) {
            pref[i + 1] = pref[i] + cross(p[i], p[i + 1]);
        }

        double minLen = Double.POSITIVE_INFINITY;
        double maxLen = 0.0;

        int j = 1;
        final double EPS = 1e-12;

        for (int i = 0; i < n; i++) {
            if (j < i + 1) j = i + 1;

            while (j + 1 <= i + n &&
                    chainArea2(p, pref, i, j + 1) <= half2 + EPS) {
                j++;
            }

            // Now area(i..j) <= half2 < area(i..j+1), and target point lies on edge j->j+1
            double cur2 = chainArea2(p, pref, i, j);
            Pt A = p[j];
            Pt B = p[j + 1];

            double need = half2 - cur2; // additional doubled area needed
            double denom = cross(A, B) + cross(B, p[i]) + cross(p[i], A); // = cross(A-p[i], B-p[i])

            double t;
            if (Math.abs(denom) < EPS) {
                t = 0.0;
            } else {
                t = need / denom;
            }
            if (t < 0) t = 0;
            if (t > 1) t = 1;

            Pt Q = new Pt(A.x + (B.x - A.x) * t, A.y + (B.y - A.y) * t);
            double len = dist(p[i], Q);

            if (len < minLen) minLen = len;
            if (len > maxLen) maxLen = len;
        }

        System.out.printf(Locale.US, "%.10f %.10f%n", minLen, maxLen);
    }
}

#include <bits/stdc++.h>
using namespace std;
using ld = long double;
const ld EPS = 1e-9;

struct Point {
    ld x, y;
    Point() : x(0), y(0) {}
    Point(ld x, ld y) : x(x), y(y) {}
    Point operator+(const Point& p) const { return Point(x + p.x, y + p.y); }
    Point operator-(const Point& p) const { return Point(x - p.x, y - p.y); }
    Point operator*(ld s) const { return Point(x * s, y * s); }
    ld cross(const Point& p) const { return x * p.y - y * p.x; }
    ld dot(const Point& p) const { return x * p.x + y * p.y; }
    ld len() const { return sqrtl(x*x + y*y); }
};

ld polygonArea(const vector<Point>& p) {
    ld area = 0;
    int n = p.size();
    for (int i = 0; i < n; i++)
        area += p[i].cross(p[(i+1)%n]);
    return fabs(area) / 2.0;
}

Point centroid(const vector<Point>& p) {
    ld cx = 0, cy = 0;
    ld area = 0;
    int n = p.size();
    for (int i = 0; i < n; i++) {
        ld cross = p[i].cross(p[(i+1)%n]);
        area += cross;
        cx += (p[i].x + p[(i+1)%n].x) * cross;
        cy += (p[i].y + p[(i+1)%n].y) * cross;
    }
    area /= 2.0;
    cx /= (6.0 * area);
    cy /= (6.0 * area);
    return Point(cx, cy);
}

// Intersection of line A->B and C->D
Point lineIntersect(Point a, Point b, Point c, Point d) {
    Point v1 = b - a, v2 = d - c;
    ld t = (c - a).cross(v2) / v1.cross(v2);
    return a + v1 * t;
}

// chord through centroid in direction dir, find intersection with polygon edge from i to i+1
pair<Point,Point> chordIntersect(const vector<Point>& poly, Point dir, Point c) {
    int n = poly.size();
    Point p1, p2;
    int found = 0;
    for (int i = 0; i < n; i++) {
        Point a = poly[i], b = poly[(i+1)%n];
        Point v = b - a;
        // line through c with direction dir: c + t*dir
        // edge: a + s*v
        ld denom = dir.cross(v);
        if (fabs(denom) < EPS) continue;
        ld t = (a - c).cross(v) / denom;
        ld s = (a - c).cross(dir) / denom;
        if (s >= -EPS && s <= 1+EPS) {
            Point pt = c + dir * t;
            if (found == 0) p1 = pt;
            else p2 = pt;
            found++;
        }
    }
    return {p1, p2};
}

ld chordLength(const vector<Point>& poly, Point dir, Point c) {
    auto [p1, p2] = chordIntersect(poly, dir, c);
    return (p1 - p2).len();
}

