    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(12);

    int n;
    cin >> n;
    vector<Point> poly(n);
    for (int i = 0; i < n; i++) {
        cin >> poly[i].x >> poly[i].y;
    }

    ld totalArea = polygonArea(poly);
    Point c = centroid(poly);

    vector<ld> candidates;

    // chords through each vertex
    for (int i = 0; i < n; i++) {
        Point v = poly[i];
        // binary search for point on opposite side to split area
        int j = (i+1)%n;
        while (true) {
            Point a = poly[j], b = poly[(j+1)%n];
            // line from v to point on a-b, find where area left = total/2
            ld lo = 0, hi = 1;
            for (int iter = 0; iter < 60; iter++) {
                ld mid = (lo+hi)/2;
                Point pt = a + (b - a) * mid;
                // compute area of polygon part on one side of line v->pt
                // sum area of polygon v -> ... -> pt
                ld areaLeft = 0;
                // area of polygon v, poly[i+1], ..., poly[j], pt
                vector<Point> test;
                test.push_back(v);
                int idx = (i+1)%n;
                while (idx != (j+1)%n) {
                    test.push_back(poly[idx]);
                    idx = (idx+1)%n;
                }
                test.push_back(pt);
                areaLeft = polygonArea(test);
                if (areaLeft < totalArea/2) lo = mid;
                else hi = mid;
            }
            Point pt = a + (b - a) * ((lo+hi)/2);
            ld len = (v - pt).len();
            candidates.push_back(len);
            // move to next edge
            j = (j+1)%n;
            if (j == i) break;
        }
    }

    // chords through centroid parallel to each edge
    for (int i = 0; i < n; i++) {
        Point dir = poly[(i+1)%n] - poly[i];
        dir = Point(-dir.y, dir.x); // perpendicular direction
        if (dir.len() > EPS) {
            ld len = chordLength(poly, dir, c);
            candidates.push_back(len);
        }
    }

    ld minLen = *min_element(candidates.begin(), candidates.end());
    ld maxLen = *max_element(candidates.begin(), candidates.end());

    cout << minLen << "\n" << maxLen << "\n";

    return 0;
}

