#include <bits/stdc++.h>
using namespace std;

static const double EPS = 1e-12;

struct Pt {
    double x, y;
    Pt() {}
    Pt(double x_, double y_) : x(x_), y(y_) {}
    Pt operator + (const Pt& o) const { return Pt(x + o.x, y + o.y); }
    Pt operator - (const Pt& o) const { return Pt(x - o.x, y - o.y); }
    Pt operator * (double k) const { return Pt(x * k, y * k); }
};

double cross(const Pt& a, const Pt& b) {
    return a.x * b.y - a.y * b.x;
}

double dot(const Pt& a, const Pt& b) {
    return a.x * b.x + a.y * b.y;
}

double norm(const Pt& a) {
    return sqrt(dot(a, a));
}

Pt lineIntersection(const Pt& a, const Pt& b, const Pt& c, const Pt& d) {
    // intersection of lines ab and cd
    Pt r = b - a, s = d - c;
    double t = cross(c - a, s) / cross(r, s);
    return a + r * t;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cout.setf(std::ios::fixed);
    cout << setprecision(3);

    while (cin >> n) {
        if (n < 3) break;

        vector<Pt> p(n);
        for (int i = 0; i < n; ++i) cin >> p[i].x >> p[i].y;

        // Ensure CCW
        double signedArea2 = 0.0;
        for (int i = 0; i < n; ++i) signedArea2 += cross(p[i], p[(i + 1) % n]);
        if (signedArea2 < 0) reverse(p.begin(), p.end());

        // Duplicate vertices for cyclic handling
        vector<Pt> q(2 * n + 1);
        for (int i = 0; i < 2 * n; ++i) q[i] = p[i % n];
        q[2 * n] = q[0];

        // Prefix sums of cross products
        vector<double> pref(2 * n + 1, 0.0);
        for (int i = 0; i < 2 * n; ++i) {
            pref[i + 1] = pref[i] + cross(q[i], q[i + 1]);
        }

        auto areaChain2 = [&](int i, int j) -> double {
            // doubled signed area of polygonal chain q[i..j]
            // closed by segment q[j] -> q[i]
            return (pref[j] - pref[i]) + cross(q[j], q[i]);
        };

        double total2 = fabs(signedArea2);
        double half2 = total2 / 2.0;

        auto pointOnEdge = [&](int idx, double t) -> Pt {
            // point on edge q[idx] -> q[idx+1], t in [0,1]
            return q[idx] + (q[idx + 1] - q[idx]) * t;
        };

        vector<pair<Pt, Pt>> cuts;

        int j = 1;
        for (int i = 0; i < n; ++i) {
            if (j < i + 1) j = i + 1;

            while (j < i + n && areaChain2(i, j) < half2 - EPS) ++j;

            // Need solution between edge from j-1 to j, with start fixed at vertex i
            if (j <= i + n - 1) {
                double A = areaChain2(i, j - 1);
                double need = half2 - A;
                Pt e = q[j] - q[j - 1];
                double denom = cross(e, q[i] - q[j - 1]); // area contribution coefficient
                if (fabs(denom) > EPS) {
                    double t = need / denom;
                    if (t > -EPS && t < 1 + EPS) {
                        t = max(0.0, min(1.0, t));
                        Pt y = pointOnEdge(j - 1, t);
                        cuts.push_back({q[i], y});
                    }
                }
            }

            // Also solution where endpoint is fixed at vertex j and start moves on edge i->i+1
            if (j < i + n) {
                double B = areaChain2(i + 1, j);
                double need = half2 - B;
                Pt e = q[i + 1] - q[i];
                double denom = cross(q[j] - q[i], e);
                if (fabs(denom) > EPS) {
                    double t = need / denom;
                    if (t > -EPS && t < 1 + EPS) {
                        t = max(0.0, min(1.0, t));
                        Pt x = pointOnEdge(i, t);
                        cuts.push_back({x, q[j]});
                    }
                }
            }
        }

        // Remove duplicates approximately
        vector<pair<Pt, Pt>> uniq;
        auto samePt = [&](const Pt& a, const Pt& b) {
            return fabs(a.x - b.x) < 1e-8 && fabs(a.y - b.y) < 1e-8;
        };
        for (auto &seg : cuts) {
            Pt a = seg.first, b = seg.second;
            if (a.x > b.x + 1e-8 || (fabs(a.x - b.x) < 1e-8 && a.y > b.y + 1e-8))
                swap(a, b);
            bool ok = true;
            for (auto &u : uniq) {
                if (samePt(a, u.first) && samePt(b, u.second)) {
                    ok = false;
                    break;
                }
            }
            if (ok) uniq.push_back({a, b});
        }

        double mn = 1e100, mx = 0.0;
        for (auto &seg : uniq) {
            double len = norm(seg.first - seg.second);
            mn = min(mn, len);
            mx = max(mx, len);
        }

        cout << mn << " " << mx << "\n";
    }

    return 0;
}
